/**
 * Cascade behind `ProjectService.archiveProject`; returns the row count. Only
 * the still-live issues of the project are stamped, so issues archived earlier
 * keep their original `archived_at` and are not counted again.
 */
export async function archiveIssuesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const rows = getDb()
    .update(issues)
    .set(archivePatch())
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, projectId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )

